fn encode(message: Vec<char>) -> Vec<char> {
    // Helper to map a vowel to its replacement
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _ => unreachable!(),
        }
    }

    // Helper to swap ASCII letter case
    fn swap_case(c: char) -> char {
        if c.is_ascii_lowercase() {
            c.to_ascii_uppercase()
        } else {
            c.to_ascii_lowercase()
        }
    }

    let mut result = Vec::with_capacity(message.len());
    for c in message {
        let out = match c {
            ' ' => ' ',
            // Vowels get mapped then have their case swapped
            'a' | 'e' | 'i' | 'o' | 'u'
            | 'A' | 'E' | 'I' | 'O' | 'U' => {
                let mapped = map_vowel(c);
                swap_case(mapped)
            }
            // Consonants just swap case
            _ => swap_case(c),
        };
        result.push(out);
    }
    result
}

